import{_ as e}from"./chunks/1e22359c4d5983a08a364d2c711ab776.BH8a6X41.js";import{_ as i,c as a,a2 as n,o as d}from"./chunks/framework.BnrAgU0Y.js";const m=JSON.parse('{"title":"Untitled","description":"Untitled","frontmatter":{"title":"Untitled","description":"Untitled","layout":"doc"},"headers":[],"relativePath":"langflow/concepts-api.md","filePath":"langflow/concepts-api.md"}'),s={name:"langflow/concepts-api.md"};function l(o,t,c,p,r,h){return d(),a("div",null,t[0]||(t[0]=[n('<header><h1>API pane</h1></header><p>The <strong>API</strong> pane presents code templates for integrating your flow into external applications.</p><p><img src="'+e+'" alt=""></p><h2 class="anchor anchorWithHideOnScrollNavbar_WYt5" id="curl">cURL<a href="#curl" class="hash-link" aria-label="Direct link to cURL" title="Direct link to cURL">​</a></h2><p>The <strong>cURL</strong> tab displays sample code for posting a query to your flow. Modify the <code>input_value</code> to change your input message. Copy the code and run it to post a query to your flow and get the result.</p><h2 class="anchor anchorWithHideOnScrollNavbar_WYt5" id="python-api">Python API<a href="#python-api" class="hash-link" aria-label="Direct link to Python API" title="Direct link to Python API">​</a></h2><p>The <strong>Python API</strong> tab displays code to interact with your flow using the Python HTTP <code>requests</code> library.</p><p>To use the <code>requests</code> library:</p><ol><li>Copy and paste the code into a Python script.</li><li>Run the script and pass your message with it.</li></ol><div class="ch-codeblock not-prose" data-ch-theme="github-dark"><div class="ch-code-wrapper ch-code" data-ch-measured="false"><code class="ch-code-scroll-parent"><br><div><span class="ch-code-line-number">_10</span><div style="display:inline-block;margin-left:16px;"><span>python3 python-api-script.py --message=&quot;tell me about something interesting&quot;</span></div></div><br></code></div></div><h2 class="anchor anchorWithHideOnScrollNavbar_WYt5" id="python-code">Python code<a href="#python-code" class="hash-link" aria-label="Direct link to Python code" title="Direct link to Python code">​</a></h2><p>The <strong>Python Code</strong> tab displays code to interact with your flow&#39;s <code>.json</code> file using the Langflow runtime.</p><p>To use your code in a Python application using the Langflow runtime, you have to first download your flow’s JSON file.</p><ol><li><p>In your <strong>Workspace</strong>, click <strong>Settings</strong>, and then select <strong>Export</strong>.</p></li><li><p>Download the flow to your local machine. Make sure the flow path in the script matches the flow’s location on your machine.</p></li><li><p>Copy and paste the code from the API tab into a Python script file. It will look like this:</p></li></ol><div class="ch-codeblock not-prose" data-ch-theme="github-dark"><div class="ch-code-wrapper ch-code" data-ch-measured="false"><code class="ch-code-scroll-parent"><br><div><span class="ch-code-line-number">_14</span><div style="display:inline-block;margin-left:16px;"><span>from langflow.load import run_flow_from_json</span></div></div><div><span class="ch-code-line-number">_14</span><div style="display:inline-block;margin-left:16px;"><span>TWEAKS = {</span></div></div><div><span class="ch-code-line-number">_14</span><div style="display:inline-block;margin-left:16px;"><span> &quot;ChatInput-kKhri&quot;: {},</span></div></div><div><span class="ch-code-line-number">_14</span><div style="display:inline-block;margin-left:16px;"><span> &quot;Prompt-KDSi5&quot;: {},</span></div></div><div><span class="ch-code-line-number">_14</span><div style="display:inline-block;margin-left:16px;"><span> &quot;ChatOutput-Vr3Q7&quot;: {},</span></div></div><div><span class="ch-code-line-number">_14</span><div style="display:inline-block;margin-left:16px;"><span> &quot;OpenAIModel-4xYtx&quot;: {}</span></div></div><div><span class="ch-code-line-number">_14</span><div style="display:inline-block;margin-left:16px;"><span>}</span></div></div><div><span class="ch-code-line-number">_14</span><div style="display:inline-block;margin-left:16px;"><span></span></div></div><div><span class="ch-code-line-number">_14</span><div style="display:inline-block;margin-left:16px;"><span>result = run_flow_from_json(flow=&quot;./basic-prompting-local.json&quot;,</span></div></div><div><span class="ch-code-line-number">_14</span><div style="display:inline-block;margin-left:16px;"><span> input_value=&quot;tell me about something interesting&quot;,</span></div></div><div><span class="ch-code-line-number">_14</span><div style="display:inline-block;margin-left:16px;"><span> fallback_to_env_vars=True, # False by default</span></div></div><div><span class="ch-code-line-number">_14</span><div style="display:inline-block;margin-left:16px;"><span> tweaks=TWEAKS)</span></div></div><div><span class="ch-code-line-number">_14</span><div style="display:inline-block;margin-left:16px;"><span></span></div></div><div><span class="ch-code-line-number">_14</span><div style="display:inline-block;margin-left:16px;"><span>print(result)</span></div></div><br></code></div></div><ol start="4"><li>Run the script:</li></ol><div class="ch-codeblock not-prose" data-ch-theme="github-dark"><div class="ch-code-wrapper ch-code" data-ch-measured="false"><code class="ch-code-scroll-parent"><br><div><span class="ch-code-line-number">_10</span><div style="display:inline-block;margin-left:16px;"><span>python3 python-api-script.py</span></div></div><br></code></div></div><h2 class="anchor anchorWithHideOnScrollNavbar_WYt5" id="tweaks">Tweaks<a href="#tweaks" class="hash-link" aria-label="Direct link to Tweaks" title="Direct link to Tweaks">​</a></h2><p>The <strong>Tweaks</strong> tab displays the available parameters for your flow. Modifying the parameters changes the code parameters across all windows. For example, changing the <strong>Chat Input</strong> component&#39;s <code>input_value</code> will change that value across all API calls.</p><h2 class="anchor anchorWithHideOnScrollNavbar_WYt5" id="send-image-files-to-your-flow-with-the-api">Send image files to your flow with the API<a href="#send-image-files-to-your-flow-with-the-api" class="hash-link" aria-label="Direct link to Send image files to your flow with the API" title="Direct link to Send image files to your flow with the API">​</a></h2><p>For information on sending files to the Langflow API, see <a href="/api-reference-api-examples#upload-image-files">API examples</a>.</p><h2 class="anchor anchorWithHideOnScrollNavbar_WYt5" id="chat-widget">Chat Widget<a href="#chat-widget" class="hash-link" aria-label="Direct link to Chat Widget" title="Direct link to Chat Widget">​</a></h2><p>The <strong>Chat Widget HTML</strong> tab displays code that can be inserted in the <code>&lt;body&gt;</code> of your HTML to interact with your flow.</p><p>The <strong>Langflow Chat Widget</strong> is a powerful web component that enables communication with a Langflow project. This widget allows for a chat interface embedding, allowing the integration of Langflow into web applications effortlessly.</p><p>You can get the HTML code embedded with the chat by clicking the Code button at the Sidebar after building a flow.</p><p>Clicking the Chat Widget HTML tab, you&#39;ll get the code to be inserted. Read below to learn how to use it with HTML, React and Angular.</p><h3 class="anchor anchorWithHideOnScrollNavbar_WYt5" id="embed-the-chat-widget-into-html">Embed the chat widget into HTML<a href="#embed-the-chat-widget-into-html" class="hash-link" aria-label="Direct link to Embed the chat widget into HTML" title="Direct link to Embed the chat widget into HTML">​</a></h3><p>To embed the chat widget into any HTML page, insert the code snippet. inside a <code>&lt;body&gt;</code> tag.</p><div class="ch-codeblock not-prose" data-ch-theme="github-dark"><div class="ch-code-wrapper ch-code" data-ch-measured="false"><code class="ch-code-scroll-parent"><br><div><span class="ch-code-line-number">_10</span><div style="display:inline-block;margin-left:16px;"><span>&lt;script src=&quot;https://cdn.jsdelivr.net/gh/logspace-ai/langflow-embedded-chat@v1.0.7/dist/build/static/js/bundle.min.js&quot;&quot;&gt;&lt;/script&gt;</span></div></div><div><span class="ch-code-line-number">_10</span><div style="display:inline-block;margin-left:16px;"><span></span></div></div><div><span class="ch-code-line-number">_10</span><div style="display:inline-block;margin-left:16px;"><span> &lt;langflow-chat</span></div></div><div><span class="ch-code-line-number">_10</span><div style="display:inline-block;margin-left:16px;"><span> window_title=&quot;Basic Prompting&quot;</span></div></div><div><span class="ch-code-line-number">_10</span><div style="display:inline-block;margin-left:16px;"><span> flow_id=&quot;801abb1e-19b9-4278-9632-179b6d84f126&quot;</span></div></div><div><span class="ch-code-line-number">_10</span><div style="display:inline-block;margin-left:16px;"><span> host_url=&quot;http://localhost:7860&quot;</span></div></div><div><span class="ch-code-line-number">_10</span><div style="display:inline-block;margin-left:16px;"><span></span></div></div><div><span class="ch-code-line-number">_10</span><div style="display:inline-block;margin-left:16px;"><span> &gt;&lt;/langflow-chat&gt;</span></div></div><br></code></div></div><h3 class="anchor anchorWithHideOnScrollNavbar_WYt5" id="embed-the-chat-widget-with-react">Embed the chat widget with React<a href="#embed-the-chat-widget-with-react" class="hash-link" aria-label="Direct link to Embed the chat widget with React" title="Direct link to Embed the chat widget with React">​</a></h3><p>To embed the Chat Widget using React, insert this <code>&lt;script&gt;</code> tag into the React <em>index.html</em> file, inside the <code>&lt;body&gt;</code>tag:</p><div class="ch-codeblock not-prose" data-ch-theme="github-dark"><div class="ch-code-wrapper ch-code" data-ch-measured="false"><code class="ch-code-scroll-parent"><br><div><span class="ch-code-line-number">_10</span><div style="display:inline-block;margin-left:16px;"><span>&lt;script src=&quot;https://cdn.jsdelivr.net/gh/langflow-ai/langflow-embedded-chat@main/dist/build/static/js/bundle.min.js&quot;&gt;&lt;/script&gt;</span></div></div><br></code></div></div><p>Declare your Web Component and encapsulate it in a React component.</p><div class="ch-codeblock not-prose" data-ch-theme="github-dark"><div class="ch-code-wrapper ch-code" data-ch-measured="false"><code class="ch-code-scroll-parent"><br><div><span class="ch-code-line-number">_20</span><div style="display:inline-block;margin-left:16px;"><span>declare global {</span></div></div><div><span class="ch-code-line-number">_20</span><div style="display:inline-block;margin-left:16px;"><span> namespace JSX {</span></div></div><div><span class="ch-code-line-number">_20</span><div style="display:inline-block;margin-left:16px;"><span> interface IntrinsicElements {</span></div></div><div><span class="ch-code-line-number">_20</span><div style="display:inline-block;margin-left:16px;"><span> &quot;langflow-chat&quot;: any;</span></div></div><div><span class="ch-code-line-number">_20</span><div style="display:inline-block;margin-left:16px;"><span> }</span></div></div><div><span class="ch-code-line-number">_20</span><div style="display:inline-block;margin-left:16px;"><span> }</span></div></div><div><span class="ch-code-line-number">_20</span><div style="display:inline-block;margin-left:16px;"><span>}</span></div></div><div><span class="ch-code-line-number">_20</span><div style="display:inline-block;margin-left:16px;"><span></span></div></div><div><span class="ch-code-line-number">_20</span><div style="display:inline-block;margin-left:16px;"><span>export default function ChatWidget({ className }) {</span></div></div><div><span class="ch-code-line-number">_20</span><div style="display:inline-block;margin-left:16px;"><span> return (</span></div></div><div><span class="ch-code-line-number">_20</span><div style="display:inline-block;margin-left:16px;"><span> &lt;div className={className}&gt;</span></div></div><div><span class="ch-code-line-number">_20</span><div style="display:inline-block;margin-left:16px;"><span> &lt;langflow-chat</span></div></div><div><span class="ch-code-line-number">_20</span><div style="display:inline-block;margin-left:16px;"><span> chat_inputs=&#39;{&quot;your_key&quot;:&quot;value&quot;}&#39;</span></div></div><div><span class="ch-code-line-number">_20</span><div style="display:inline-block;margin-left:16px;"><span> chat_input_field=&quot;your_chat_key&quot;</span></div></div><div><span class="ch-code-line-number">_20</span><div style="display:inline-block;margin-left:16px;"><span> flow_id=&quot;your_flow_id&quot;</span></div></div><div><span class="ch-code-line-number">_20</span><div style="display:inline-block;margin-left:16px;"><span> host_url=&quot;langflow_url&quot;</span></div></div><div><span class="ch-code-line-number">_20</span><div style="display:inline-block;margin-left:16px;"><span> &gt;&lt;/langflow-chat&gt;</span></div></div><div><span class="ch-code-line-number">_20</span><div style="display:inline-block;margin-left:16px;"><span> &lt;/div&gt;</span></div></div><div><span class="ch-code-line-number">_20</span><div style="display:inline-block;margin-left:16px;"><span> );</span></div></div><div><span class="ch-code-line-number">_20</span><div style="display:inline-block;margin-left:16px;"><span>}</span></div></div><br></code></div></div><p>Place the component anywhere in your code to display the Chat Widget.</p><h3 class="anchor anchorWithHideOnScrollNavbar_WYt5" id="embed-the-chat-widget-with-angular">Embed the chat widget with Angular<a href="#embed-the-chat-widget-with-angular" class="hash-link" aria-label="Direct link to Embed the chat widget with Angular" title="Direct link to Embed the chat widget with Angular">​</a></h3><p>To use the chat widget in Angular, first add this <code>&lt;script&gt;</code> tag into the Angular <em>index.html</em> file, inside the <code>&lt;body&gt;</code> tag.</p><div class="ch-codeblock not-prose" data-ch-theme="github-dark"><div class="ch-code-wrapper ch-code" data-ch-measured="false"><code class="ch-code-scroll-parent"><br><div><span class="ch-code-line-number">_10</span><div style="display:inline-block;margin-left:16px;"><span>&lt;script src=&quot;https://cdn.jsdelivr.net/gh/langflow-ai/langflow-embedded-chat@main/dist/build/static/js/bundle.min.js&quot;&gt;&lt;/script&gt;</span></div></div><br></code></div></div><p>When you use a custom web component in an Angular template, the Angular compiler might show a warning when it doesn&#39;t recognize the custom elements by default. To suppress this warning, add <code>CUSTOM_ELEMENTS_SCHEMA</code> to the module&#39;s <code>@NgModule.schemas</code>.</p><ul><li>Open the module file (it typically ends with <em>.module.ts</em>) where you&#39;d add the <code>langflow-chat</code> web component.</li><li>Import <code>CUSTOM_ELEMENTS_SCHEMA</code> at the top of the file:</li></ul><p><code>import { NgModule, CUSTOM_ELEMENTS_SCHEMA } from &#39;@angular/core&#39;;</code></p><ul><li>Add <code>CUSTOM_ELEMENTS_SCHEMA</code> to the &#39;schemas&#39; array inside the &#39;@NgModule&#39; decorator:</li></ul><div class="ch-codeblock not-prose" data-ch-theme="github-dark"><div class="ch-code-wrapper ch-code" data-ch-measured="false"><code class="ch-code-scroll-parent"><br><div><span class="ch-code-line-number">_12</span><div style="display:inline-block;margin-left:16px;"><span>@NgModule({</span></div></div><div><span class="ch-code-line-number">_12</span><div style="display:inline-block;margin-left:16px;"><span> declarations: [</span></div></div><div><span class="ch-code-line-number">_12</span><div style="display:inline-block;margin-left:16px;"><span> // ... Other components and directives ...</span></div></div><div><span class="ch-code-line-number">_12</span><div style="display:inline-block;margin-left:16px;"><span> ],</span></div></div><div><span class="ch-code-line-number">_12</span><div style="display:inline-block;margin-left:16px;"><span> imports: [</span></div></div><div><span class="ch-code-line-number">_12</span><div style="display:inline-block;margin-left:16px;"><span> // ... Other imported modules ...</span></div></div><div><span class="ch-code-line-number">_12</span><div style="display:inline-block;margin-left:16px;"><span> ],</span></div></div><div><span class="ch-code-line-number">_12</span><div style="display:inline-block;margin-left:16px;"><span> schemas: [</span></div></div><div><span class="ch-code-line-number">_12</span><div style="display:inline-block;margin-left:16px;"><span> CUSTOM_ELEMENTS_SCHEMA // Add the CUSTOM_ELEMENTS_SCHEMA here</span></div></div><div><span class="ch-code-line-number">_12</span><div style="display:inline-block;margin-left:16px;"><span> ]</span></div></div><div><span class="ch-code-line-number">_12</span><div style="display:inline-block;margin-left:16px;"><span>})</span></div></div><div><span class="ch-code-line-number">_12</span><div style="display:inline-block;margin-left:16px;"><span>export class YourModule { }</span></div></div><br></code></div></div><p>In your Angular project, find the component belonging to the module where <code>CUSTOM_ELEMENTS_SCHEMA</code> was added. Inside the template, add the <code>langflow-chat</code> tag to include the Chat Widget in your component&#39;s view:</p><div class="ch-codeblock not-prose" data-ch-theme="github-dark"><div class="ch-code-wrapper ch-code" data-ch-measured="false"><code class="ch-code-scroll-parent"><br><div><span class="ch-code-line-number">_10</span><div style="display:inline-block;margin-left:16px;"><span>&lt;langflow-chat chat_inputs=&#39;{&quot;your_key&quot;:&quot;value&quot;}&#39; chat_input_field=&quot;your_chat_key&quot; flow_id=&quot;your_flow_id&quot; host_url=&quot;langflow_url&quot;&gt;&lt;/langflow-chat&gt;</span></div></div><br></code></div></div><div class="theme-admonition theme-admonition-tip admonition_xJq3 alert alert--success"><div class="admonitionHeading_Gvgb"><span class="admonitionIcon_Rf37"><svg viewBox="0 0 12 16"><path fill-rule="evenodd" d="M6.5 0C3.48 0 1 2.19 1 5c0 .92.55 2.25 1 3 1.34 2.25 1.78 2.78 2 4v1h5v-1c.22-1.22.66-1.75 2-4 .45-.75 1-2.08 1-3 0-2.81-2.48-5-5.5-5zm3.64 7.48c-.25.44-.47.8-.67 1.11-.86 1.41-1.25 2.06-1.45 3.23-.02.05-.02.11-.02.17H5c0-.06 0-.13-.02-.17-.2-1.17-.59-1.83-1.45-3.23-.2-.31-.42-.67-.67-1.11C2.44 6.78 2 5.65 2 5c0-2.2 2.02-4 4.5-4 1.22 0 2.36.42 3.22 1.19C10.55 2.94 11 3.94 11 5c0 .66-.44 1.78-.86 2.48zM4 14h5c-.23 1.14-1.3 2-2.5 2s-2.27-.86-2.5-2z"></path></svg></span>tip</div><div class="admonitionContent_BuS1"><p><code>CUSTOM_ELEMENTS_SCHEMA</code> is a built-in schema that allows Angular to recognize custom elements. Adding <code>CUSTOM_ELEMENTS_SCHEMA</code> tells Angular to allow custom elements in your templates, and it will suppress the warning related to unknown elements like <code>langflow-chat</code>. Notice that you can only use the Chat Widget in components that are part of the module where you added <code>CUSTOM_ELEMENTS_SCHEMA</code>.</p></div></div><h2 class="anchor anchorWithHideOnScrollNavbar_WYt5" id="chat-widget-configuration">Chat widget configuration<a href="#chat-widget-configuration" class="hash-link" aria-label="Direct link to Chat widget configuration" title="Direct link to Chat widget configuration">​</a></h2><p>Use the widget API to customize your Chat Widget:</p><div class="theme-admonition theme-admonition-caution admonition_xJq3 alert alert--warning"><div class="admonitionHeading_Gvgb"><span class="admonitionIcon_Rf37"><svg viewBox="0 0 16 16"><path fill-rule="evenodd" d="M8.893 1.5c-.183-.31-.52-.5-.887-.5s-.703.19-.886.5L.138 13.499a.98.98 0 0 0 0 1.001c.193.31.53.501.886.501h13.964c.367 0 .704-.19.877-.5a1.03 1.03 0 0 0 .01-1.002L8.893 1.5zm.133 11.497H6.987v-2.003h2.039v2.003zm0-3.004H6.987V5.987h2.039v4.006z"></path></svg></span>caution</div><div class="admonitionContent_BuS1"><p>Props with the type JSON need to be passed as stringified JSONs, with the format {&quot;key&quot;:&quot;value&quot;}.</p></div></div><table><thead><tr><th>Prop</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td>bot_message_style</td><td>JSON</td><td>No</td><td>Applies custom formatting to bot messages.</td></tr><tr><td>chat_input_field</td><td>String</td><td>Yes</td><td>Defines the type of the input field for chat messages.</td></tr><tr><td>chat_inputs</td><td>JSON</td><td>Yes</td><td>Determines the chat input elements and their respective values.</td></tr><tr><td>chat_output_key</td><td>String</td><td>No</td><td>Specifies which output to display if multiple outputs are available.</td></tr><tr><td>chat_position</td><td>String</td><td>No</td><td>Positions the chat window on the screen (options include: top-left, top-center, top-right, center-left, center-right, bottom-right, bottom-center, bottom-left).</td></tr><tr><td>chat_trigger_style</td><td>JSON</td><td>No</td><td>Styles the chat trigger button.</td></tr><tr><td>chat_window_style</td><td>JSON</td><td>No</td><td>Customizes the overall appearance of the chat window.</td></tr><tr><td>error_message_style</td><td>JSON</td><td>No</td><td>Sets the format for error messages within the chat window.</td></tr><tr><td>flow_id</td><td>String</td><td>Yes</td><td>Identifies the flow that the component is associated with.</td></tr><tr><td>height</td><td>Number</td><td>No</td><td>Sets the height of the chat window in pixels.</td></tr><tr><td>host_url</td><td>String</td><td>Yes</td><td>Specifies the URL of the host for chat component communication.</td></tr><tr><td>input_container_style</td><td>JSON</td><td>No</td><td>Applies styling to the container where chat messages are entered.</td></tr><tr><td>input_style</td><td>JSON</td><td>No</td><td>Sets the style for the chat input field.</td></tr><tr><td>online</td><td>Boolean</td><td>No</td><td>Toggles the online status of the chat component.</td></tr><tr><td>online_message</td><td>String</td><td>No</td><td>Sets a custom message to display when the chat component is online.</td></tr><tr><td>placeholder</td><td>String</td><td>No</td><td>Sets the placeholder text for the chat input field.</td></tr><tr><td>placeholder_sending</td><td>String</td><td>No</td><td>Sets the placeholder text to display while a message is being sent.</td></tr><tr><td>send_button_style</td><td>JSON</td><td>No</td><td>Sets the style for the send button in the chat window.</td></tr><tr><td>send_icon_style</td><td>JSON</td><td>No</td><td>Sets the style for the send icon in the chat window.</td></tr><tr><td>tweaks</td><td>JSON</td><td>No</td><td>Applies additional custom adjustments for the associated flow.</td></tr><tr><td>user_message_style</td><td>JSON</td><td>No</td><td>Determines the formatting for user messages in the chat window.</td></tr><tr><td>width</td><td>Number</td><td>No</td><td>Sets the width of the chat window in pixels.</td></tr><tr><td>window_title</td><td>String</td><td>No</td><td>Sets the title displayed in the chat window&#39;s header or title bar.</td></tr></tbody></table><h2 class="anchor anchorWithHideOnScrollNavbar_WYt5" id="webhook-curl">Webhook cURL<a href="#webhook-curl" class="hash-link" aria-label="Direct link to Webhook cURL" title="Direct link to Webhook cURL">​</a></h2><p>When a <strong>Webhook</strong> component is added to the workspace, a new <strong>Webhook cURL</strong> tab becomes available in the <strong>API</strong> pane that contains an HTTP POST request for triggering the webhook component. For example:</p><div class="ch-codeblock not-prose" data-ch-theme="github-dark"><div class="ch-code-wrapper ch-code" data-ch-measured="false"><code class="ch-code-scroll-parent"><br><div><span class="ch-code-line-number">_10</span><div style="display:inline-block;margin-left:16px;"><span>curl -X POST \\</span></div></div><div><span class="ch-code-line-number">_10</span><div style="display:inline-block;margin-left:16px;"><span> &quot;http://127.0.0.1:7860/api/v1/webhook/**YOUR_FLOW_ID**&quot; \\</span></div></div><div><span class="ch-code-line-number">_10</span><div style="display:inline-block;margin-left:16px;"><span> -H &#39;Content-Type: application/json&#39;\\</span></div></div><div><span class="ch-code-line-number">_10</span><div style="display:inline-block;margin-left:16px;"><span> -d &#39;{&quot;any&quot;: &quot;data&quot;}&#39;</span></div></div><br></code></div></div><p>To test the <strong>Webhook</strong> component in your flow, see the <a href="/components-data#webhook">Webhook component</a>.</p>',54)]))}const g=i(s,[["render",l]]);export{m as __pageData,g as default};
